    setPrg8 (slot, bank) { this.prgMap[slot] = (((bank % this.n8) + this.n8) % this.n8) * 0x2000; }
    setPrg16 (slot, bank) { const b = bank < 0 ? (this.n8 >> 1) + bank : bank; this.setPrg8(slot * 2, b * 2); this.setPrg8(slot * 2 + 1, b * 2 + 1); }
