    setChr4 (slot, bank) { for (let i = 0; i < 4; i++) this.setChr1(slot * 4 + i, bank * 4 + i); }
    setChr8 (bank) { for (let i = 0; i < 8; i++) this.setChr1(i, bank * 8 + i); }

