          const s = this.idleSt, p = (this.n << 3) | (this.v << 2) | (this.z << 1) | this.c, e = (this.pbr << 16) | to;
          if (s[0] === e && s[1] === this.a && s[2] === this.x && s[3] === this.y && s[4] === p) this.idle = true;
          else { s[0] = e; s[1] = this.a; s[2] = this.x; s[3] = this.y; s[4] = p; }
