  const WM_BTN = { left: 0x0001, right: 0x0002, down: 0x0004, up: 0x0008, plus: 0x0010, two: 0x0100, one: 0x0200, b: 0x0400, a: 0x0800, minus: 0x1000, home: 0x8000 };
