      // ---- cabecera (se ejecuta una vez por estado): valores fijos del dibujo
      const H = ['const cl = H.cl, cl4 = H.cl4, wrap = H.wrap, logic = H.logic, efb = gx.efb, zbuf = gx.zbuf, tc = gx._tc;',
        'const reg0 = st.reg0, ref0 = st.ref0, ref1 = st.ref1, fogA = st.fogA, fogB = st.fogB, fogC = st.fogC, fogS = st.fogShift, fogR = st.fogR, fogG = st.fogG, fogBl = st.fogBl;'];
      for (let r = 0; r < 16; r++) H.push('const RG' + r + ' = reg0[' + r + '];');
