            L.push('const u = S * W' + s + ' - 0.5, v = U * H' + s + ' - 0.5, u0 = Math.floor(u), v0 = Math.floor(v), fu = u - u0, fv = v - v0;');
            const wr = (c, n, m) => (m === 0 ? '(' + c + ' < 0 ? 0 : ' + c + ' >= ' + n + ' ? ' + n + ' - 1 : ' + c + ')' : m === 1 ? '(((' + c + ' % ' + n + ') + ' + n + ') % ' + n + ')' : 'wrap(' + c + ', ' + n + ', ' + m + ')');
            const WS = sg.tex.wrapS, WT = sg.tex.wrapT, Wn = 'W' + s, Hn = 'H' + s;
            L.push('const u1 = u0 + 1, v1 = v0 + 1, x0 = ' + wr('u0', Wn, WS) + ', x1 = ' + wr('u1', Wn, WS) + ', y0 = ' + wr('v0', Hn, WT) + ' * ' + Wn + ', y1 = ' + wr('v1', Hn, WT) + ' * ' + Wn + ';');
            L.push('const p00 = P' + s + '[y0 + x0], p01 = P' + s + '[y0 + x1], p10 = P' + s + '[y1 + x0], p11 = P' + s + '[y1 + x1];');
            L.push('const w00 = (1 - fu) * (1 - fv), w01 = fu * (1 - fv), w10 = (1 - fu) * fv, w11 = fu * fv;');
            const one = (sh, j) => { const e = q => (j === 3 ? '(' + q + ' >>> 24)' : '((' + q + ' >> ' + sh + ') & 255)'); return '0 + ' + e('p00') + ' * w00 / 255 + ' + e('p01') + ' * w01 / 255 + ' + e('p10') + ' * w10 / 255 + ' + e('p11') + ' * w11 / 255'; };
