      if (st.zTop && st.zOn && st.zUpd) this.zbuf[i] = zi;               // Z antes de la textura: se escribe aunque falle el alfa
      const R = this._R, tc = this._tc, ras = this._ras, res = this._res, A = this._iA, B = this._iB, C = this._iC, D = this._iD, ind = this._ind;
