        if (!this.dstTex) { this.dstTex = gl.createTexture(); gl.bindTexture(gl.TEXTURE_2D, this.dstTex); gl.texImage2D(gl.TEXTURE_2D, 0, gl.RGBA8, GX_W, GX_H, 0, gl.RGBA, gl.UNSIGNED_BYTE, null); }
