      const tc = ['aT01.xy', 'aT01.zw', 'aT23.xy', 'aT23.zw', 'aT45.xy', 'aT45.zw', 'aT67.xy', 'aT67.zw'];
      const tmI = i => 'int(' + (i < 4 ? 'aTM0' : 'aTM1') + '.' + 'xyzw'[i & 3] + ' + 0.5)';
