            L.push('float q2 = xp(' + (b + 8) + ') * s + xp(' + (b + 9) + ') * t + xp(' + (b + 10) + ') * q + xp(' + (b + 11) + '); s = s2; t = t2; q = ' + (g.proj ? 'q2' : '1.0') + '; }');
