      L.push('gl_Position = vec4(((vp(3) - 342.0) / ' + f(GX_W / 2) + ' - 1.0) * cw + vp(0) * cx / ' + f(GX_W / 2) + ',');
      L.push('  (1.0 - (vp(4) - 342.0) / ' + f(GX_H / 2) + ') * cw - vp(1) * cy / ' + f(GX_H / 2) + ',');
      L.push('  ((vp(5) - 0.5) / 16777215.0 * 2.0 - 1.0) * cw + vp(2) * cz / 16777215.0 * 2.0, cw);');
