      st.stages.forEach((sg, s) => { ks[s * 4] = sg.k[0]; ks[s * 4 + 1] = sg.k[1]; ks[s * 4 + 2] = sg.k[2]; ks[s * 4 + 3] = sg.ka; });
      gl.uniform4fv(P.u.uK, ks);
