      const key = T.wrapS + ':' + T.wrapT + ':' + T.mag + ':' + T.minLin + ':' + (lv.length > 1 ? T.mip : 0) + ':' + T.minLod + ':' + T.maxLod;
      let smp = this.samplers.get(key);
