        if (this.xfbLazy.size >= 8) { const k0 = this.xfbLazy.keys().next().value, e0 = this.xfbLazy.get(k0); this.resolveXfb(gx, k0, k0 + 1); gl.deleteTexture(e0.tex); gl.deleteFramebuffer(e0.fbo); this.xfbLazy.delete(k0); }
        e = { tex: gl.createTexture(), fbo: gl.createFramebuffer() };
