      this.syncs.reads++; this.syncs.readPx += W2 * hout; { const dt = performance.now() - t0; this.syncs.readMs += dt; this.syncs.msXfb = (this.syncs.msXfb || 0) + dt; this.syncs.nXfb = (this.syncs.nXfb || 0) + 1; }
      const ram = gx.m.ram;
