      const px = this.rb.subarray(0, w * h * 4), t0 = performance.now();
      gl.readPixels(sx, GX_H - sy - h, w, h, gl.RGBA, gl.UNSIGNED_BYTE, px);
      this.syncs.reads++; this.syncs.readPx += w * h; { const dt = performance.now() - t0; this.syncs.readMs += dt; this.syncs.msZ = (this.syncs.msZ || 0) + dt; this.syncs.nZ = (this.syncs.nZ || 0) + 1; }
      for (let y = 0; y < h; y++) for (let x = 0; x < w; x++) { const o = ((h - 1 - y) * w + x) * 4; gx.zbuf[(sy + y) * GX_W + sx + x] = (px[o] << 16) | (px[o + 1] << 8) | px[o + 2]; }
