    if (entries.some(e => /^(rtld|main)$/i.test(e.name))) {
      if (fileBlob.size <= 0x20000000) return { exefs: await rd(0, fileBlob.size), romfs: null, romfsStream: null, programId: 0n };
    }

    if (!prodKeys) throw new Error('este .nsp/.xci requiere cargar primero tu archivo prod.keys (boton Abrir ROMs)');
    const ks = prodKeys instanceof NxKeySet ? prodKeys : new NxKeySet(prodKeys);
    const hdrKey = ks.get('header_key');
    if (!hdrKey || hdrKey.length < 32) throw new Error('prod.keys no tiene header_key valido');

