    HEAP: 0x1000000000, HEAP_SIZE: 0x180000000,
    ALIAS: 0x2000000000, ALIAS_SIZE: 0x1000000000,
    STACK: 0x3000000000, STACK_SIZE: 0x80000000,
    LOADER: 0x0006000000, TLS: 0x0007000000, SPACE: 0x8000000000
