      const crc = await romCrc(g, L);

      if (this.offered !== g || !this.link) return;

      // retraso: lo que tarda un paquete en llegar (media vuelta) + un margen (mas por el servidor)

      const direct = this.link && this.link.direct;

      const delay = Math.max(2, Math.min(30, Math.ceil((this.rtt / 2 + (direct ? 15 : 180)) / 16.7) + 1));

      this._reset(this.gid + 1, delay);

