  const otherSystem = name => { const m = /\.([a-z0-9]+)$/i.exec(name); return m ? OTHER_EXT[m[1].toLowerCase()] : undefined; };

  const REGIONS = [['TODAS', 'Todas'], ['EUR', 'Europa'], ['USA', 'USA'], ['JPN', 'Japón'], ['ESP', 'Español']];

  const SYSTEMS_F = [['TODOS', 'Todos'], ['GBA', 'GBA'], ['SNES', 'SNES'], ['N64', 'N64'], ['NES', 'NES'], ['DS', 'DS'], ['GC', 'GameCube'], ['WII', 'Wii'], ['NX', 'Switch']];
