    const isNro = /\.(nro|nso|nsp|pfs0|xci)$/i.test(name) || (b.length > 0x14 && b[0x10] === 0x4E && b[0x11] === 0x52 && b[0x12] === 0x4F && b[0x13] === 0x30) || (b.length >= 4 && ((b[0] === 0x4E && b[1] === 0x53 && b[2] === 0x4F && b[3] === 0x30) || (b[0] === 0x50 && b[1] === 0x46 && b[2] === 0x53 && b[3] === 0x30))) || (b.length >= 0x104 && b[0x100] === 0x48 && b[0x101] === 0x45 && b[0x102] === 0x41 && b[0x103] === 0x44);
    const isGc = isNro || /\.(iso|gcm|dol|rvz|ciso)$/i.test(name), isDol = !isNro && /\.dol$/i.test(name);

    const info = { name, system: isGc ? 'GC' : isDs ? 'DS' : isNes ? 'NES' : isN64 ? 'N64' : isSnes ? 'SNES' : 'GBA', title: '', code: '', region: 'OTRO', spanish: false,

                   hirom: 0, sram: 0, sa1: 0, skip: 0 };

    if (isNro) { info.nx = true; info.gcOk = true; info.region = 'OTRO'; info.title = name.replace(/\.(nro|nso|nsp|pfs0|xci)$/i, ''); }   // Switch (.nro / .nso / .nsp / .pfs0 / .xci)
