      const body = C(108, 84, 196), dark = C(52, 40, 104), scr = C(150, 200, 120), btn = C(230, 70, 110), dpad = C(40, 30, 70), ring = C(255, 255, 255);
      const s = 1.5 * k, cx = Math.round(W - 60 * k + (T.shake === 1 ? 2 : T.shake === 3 ? -2 : 0) * k), cy = Math.round(H - 51 * k), rad = Math.round(56 * k);
