    const note = document.createElement('div');
    note.style.cssText = 'font-size:12px;color:#8fa0c8;margin-bottom:14px';
    note.textContent = 'Versión: +0,01 por cada arreglo y +1,00 por cada consola nueva.';
    card.appendChild(note);
